def normalized(value: str) -> str:
    """Même normalisation que le service (NFKC, sans aucun espace, majuscules, L5-09)."""
    return "".join(unicodedata.normalize("NFKC", value or "").split()).upper()


def normalize_serials(apps, schema_editor):
    """Numéros existants normalisés. Doublons après normalisation : le premier (par ordre de
    création) garde son numéro, les suivants reçoivent « -DOUBLON-2 », « -DOUBLON-3 »… La liste
    est affichée et une ligne est écrite au journal d'audit de chaque entreprise concernée."""
    item_model = apps.get_model("equipment", "EquipmentItem")
    audit_model = apps.get_model("core", "AuditLog")
    groups = defaultdict(list)
    for item in item_model.objects.order_by("pk"):
        groups[(item.company_id, normalized(item.serial_number))].append(item)
    renamed = defaultdict(list)
    for (company_id, value), items in groups.items():
        for rank, item in enumerate(items, start=1):
            target = value if rank == 1 else f"{value}-DOUBLON-{rank}"
            if target != item.serial_number:
                item_model.objects.filter(pk=item.pk).update(serial_number=target)
            if rank > 1:
                renamed[company_id].append((item.serial_number, target))
    for company_id, changes in renamed.items():
        lines = [f"{old} → {new}" for old, new in changes]
        sys.stdout.write(
            f"\n  Numéros de série en double (entreprise {company_id}) : {'; '.join(lines)}\n"
        )
        audit_model.objects.create(
            company_id=company_id,
            action="equipment.serials_deduplicated",
            summary=("Numéros de série en double renommés : " + "; ".join(lines))[:255],
        )


